    i_data0,
    o_data0
);

code:
module top_module(
    i_data0,
    o_data0
);// Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0] w1, w4096, w4097, w16384, w20481, w1024, w21505, w32, w21473, w2, w21475;

  assign w1 = i_data0;
  assign w4096 = w1 << 12;
  assign w4097 = w1 + w4096;
  assign w16384 = w1 << 14;
  assign w2 = w1 << 1;
  assign w20481 = w4097 + w16384;
  assign w32 = w1 << 5;
  assign w21505 = w20481 + w1024;
  assign w21473 = w21505 - w32;
  assign w21475 = w21473 + w2;

  assign o_data0 = w21475;

  //multiplier_block area estimate = 8222.86088872941;
endmodule

