description:
Implement the Verilog module based on the following description.
Module K implements the boolean function z = x & ~y.

// Module L can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 0.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two K submodules and two L submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first K submodule is connected to a two-input AND, along with the output of the first L submodule. The second pair of K and L submodules is similarly connected to an OR gate. The output of the AND and the OR is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
	input x,
	input y,
	output z);

code:
module K(
    input x,
    input y,
    output z
);
    assign z = x & ~y;
endmodule

module L(
    input x,
    input y,
    output z
);
    assign z = x & ~y;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire k1_out, k2_out, l1_out, l2_out;
    wire and_out, or_out;

    K k1(.x(x), .y(y), .z(k1_out));
    K k2(.x(x), .y(y), .z(k2_out));
    L l1(.x(x), .y(y), .z(l1_out));
    L l2(.x(x), .y(y), .z(l2_out));

    assign and_out = k1_out & l1_out;
    assign or_out = k2_out | l2_out;

    assign z = and_out ^ or_out;
endmodule

